fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars = txt.chars();

    // Must be non-empty
    let mut prev = match chars.next() {
        Some(c) => c,
        None => return false,
    };

    // Walk to the end, tracking the previous character
    let mut last = prev;
    for c in chars {
        prev = last;
        last = c;
    }

    // Last must be an ASCII alphabetic letter
    if !last.is_ascii_alphabetic() {
        return false;
    }

    // Standalone: either single-char string, or preceded by a space
    if txt.chars().count() == 1 {
        true
    } else {
        prev == ' '
    }
}